def solution(root):
    max_sum = float('-inf')
    def get_max(node):
        nonlocal max_sum
        if not node:
            return 0
        left = max(get_max(node.left), 0)
        right = max(get_max(node.right), 0)
        curr_sum = node.val + left + right
        max_sum = max(max_sum, curr_sum)
        return node.val + max(left, right)
    get_max(root)
    return max_sum
